-- =====================================================================
-- inserts.sql - carga completa e coerente do banco gerenciador_de_pista_aeroporto
-- Uso: 1) executar creats.sql   2) executar este arquivo.
--
-- Cenario: aeroporto fictício "GPA" (região de São Paulo). "Agora" = 2026-09-23 10:00:00.
-- Horários no mesmo fuso; durações de voo são tempos de bloco aproximados.
-- Regras respeitadas nos dados:
--  * so aeronave 'Operacional' e licenciada tem voos futuros; aeronave 'Em manutencao'
--    esta em hangar e 'Aguardando inspecao' esta em portao (operacao de solo em aberto,
--    data_termino NULL); companhia suspensa nao decola.
--  * toda rota tem origem ou destino = GPA. Chegada: pista -> taxiway -> portao/hangar;
--    saida: portao/hangar -> taxiway -> pista, encadeadas por proxima_operacao.
--  * nenhuma pista, taxiway ou portao tem duas operacoes ao mesmo tempo; hangar respeita
--    a capacidade; operacao noturna so na pista 09/27 (a 18/36 nao tem luz de aproximacao).
--  * funcionarios escalados por setor e turno, apenas os 'Ativo'.
--  * ocupado = existe operacao de solo em andamento no instante 'agora'.
-- Ids explicitos. proxima_operacao aponta para uma linha inserida antes, por isso
-- Operacao_de_Solo e inserida em ordem decrescente de id.
-- =====================================================================

-- Infraestrutura (42): 1-3 hangares, 4-12 areas de manobra, 13-42 portoes

-- Manutenção de infraestrutura: histórico e situação atual (id 8 está em manutenção no cenário de referência)
UPDATE Infraestrutura SET em_manutencao = TRUE WHERE id_infraestrutura = 8;

-- Histórico ampliado de incidentes: 80 novos registros distribuídos ao longo dos dias
-- que compõem o cenário de demonstração. Todos os registros são fictícios.
